// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "solady/src/utils/FixedPointMathLib.sol";
import "./VaultTokensLib.sol";
import "./VaultFeesLib.sol";
import "./VaultStrategiesLib.sol";
import "./interfaces/IVaultSimulatorAPI.sol";
import "./interfaces/IVaultManagerAPI.sol";
import "./interfaces/IDynaVaultAPI.sol";

library VaultManagerSimulatorLib {
	using FixedPointMathLib for uint256;

	bytes32 private constant VAULT_MANAGER_SIMULATOR_LIB_STORAGE_POSITION = bytes32(uint256(keccak256("VaultManager.SimulatorLibStorage")) - 1);
	uint256 private constant MAX_TOKEN_DEBT_RATIO = 100e16; // 100.00% (debt ratio)
	uint256 private constant MAX_BPS = 100e2; // 100.00% (fees)
	uint256 private constant PRECISION = 10 ** 18;
	uint256 private constant SECS_PER_YEAR = 31_556_952;
	uint256 private constant DEGRADATION_COEFFICIENT = 10 ** 18;

	struct VaultManagerSimulatorLibStorage {
		address vault;
	}

	/**
	 * @notice returns the library storage
	 * @return ms storage pointer for accessing the state variables
	 */
	function vaultManagerSimulatorLibStorage() private pure returns (VaultManagerSimulatorLibStorage storage ms) {
		bytes32 position = VAULT_MANAGER_SIMULATOR_LIB_STORAGE_POSITION;
		assembly {
			ms.slot := position
		}
	}

	/**
	 * @notice initializes the vault simulator library setting the address of the vault
	 * @param vaultAddress address of vault
	 */
	function initialize(address vaultAddress) public {
		VaultManagerSimulatorLibStorage storage _storage = vaultManagerSimulatorLibStorage();
		_storage.vault = vaultAddress;
	}

	/**
	 * @notice simulates the current locked profit calculation using a snapshot
	 * @param snapshot The vault snapshot used in the simulation
	 * @return calculatedLockedProfitRatio should return current locked profit expressed as a ratio
	 */
	function _simulatedCalculateCurrentLockedProfitRatio(
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	) private pure returns (uint256 calculatedLockedProfitRatio) {
		uint256 _lastLockedProfitDegradation = snapshot.lastLockedProfitDegradation;
		if (snapshot.timestamp == _lastLockedProfitDegradation) return snapshot.lastLockedProfitRatio;
		uint256 _lastLockedProfitRatio = snapshot.lastLockedProfitRatio;
		uint256 _timePassed = snapshot.timestamp - _lastLockedProfitDegradation;
		uint256 _lockedProfitRatioDegradation = _timePassed * (snapshot.lockedProfitDegradationRate + snapshot.extraLockedProfitDegradationRate);
		uint256 _lockedProfitRatioDelta = FixedPointMathLib.fullMulDivUp(_lastLockedProfitRatio, _lockedProfitRatioDegradation, DEGRADATION_COEFFICIENT);
		calculatedLockedProfitRatio = _lastLockedProfitRatio > _lockedProfitRatioDelta ? _lastLockedProfitRatio - _lockedProfitRatioDelta : 0;
	}

	/**
	 * @notice simulates locked profit calculation using a snapshot
	 * @param snapshot The vault snapshot used in the simulation
	 * @return lockedProfit in deposit token
	 */
	function _simulatedLockedProfit(IVaultSimulatorAPI.VaultSnapshot memory snapshot) private pure returns (uint256 lockedProfit) {
		uint256 totalAssets = snapshot.totalAssets;
		uint256 currentLockedProfitRatio = _simulatedCalculateCurrentLockedProfitRatio(snapshot);
		lockedProfit = (currentLockedProfitRatio > 0) ? FixedPointMathLib.fullMulDiv(currentLockedProfitRatio, totalAssets, DEGRADATION_COEFFICIENT) : 0;
	}

	/**
	 * @notice Simulates the amount of free funds in the vault
	 * @param snapshot The vault snapshot used  used in the simulation
	 * @return freeFunds Simulated amount of free funds in the vault
	 */
	function simulatedFreeFunds(IVaultSimulatorAPI.VaultSnapshot memory snapshot) public pure returns (uint256 freeFunds) {
		uint256 totalAssets = snapshot.totalAssets;
		uint256 currentLockedProfitRatio = _simulatedCalculateCurrentLockedProfitRatio(snapshot);
		freeFunds = (currentLockedProfitRatio > 0)
			? FixedPointMathLib.fullMulDiv(DEGRADATION_COEFFICIENT - currentLockedProfitRatio, totalAssets, DEGRADATION_COEFFICIENT)
			: totalAssets;
	}

	/**
	 * @notice simulates unlocked profit calculation using a snapshot
	 * @param snapshot The vault snapshot used in the simulation
	 * @return ratio of unlocked funds
	 */
	function simulateUnlockedFundsRatio(IVaultSimulatorAPI.VaultSnapshot memory snapshot) external pure returns (uint256) {
		uint256 currentLockedProfitRatio = _simulatedCalculateCurrentLockedProfitRatio(snapshot);
		return DEGRADATION_COEFFICIENT - currentLockedProfitRatio;
	}

	/**
	 * @notice Should calculate the fresh profit and fees in depositTokens
	 * @notice Passes gain and totalFees in profitToken decimals
	 * @param profitToken The address of the token with profit
	 * @param deltaTotalAssets Updates total assets in fee shares calculation
	 */
	function _simulatedCalculateProfitAndFeesInDepositToken(
		address profitToken,
		uint256 deltaTotalAssets,
		uint256 totalFees
	) private view returns (uint256 deltaProfitInDepositToken, uint256 deltaFeesInDepositToken) {
		address _depositToken = VaultTokensLib.token();
		// convert gain and totalFees in deposit tokens for locked profit calculation
		uint256 _profitTokenUnit = 10 ** IERC20Metadata(profitToken).decimals();
		uint256 _profitTokenUnitInDeposit = (profitToken != _depositToken)
			? IDynaVaultAPI(VaultGovernanceLib.vault()).tokenValueInQuoteAsset(profitToken, _profitTokenUnit, _depositToken)
			: _profitTokenUnit;
		deltaProfitInDepositToken = FixedPointMathLib.fullMulDiv(deltaTotalAssets, _profitTokenUnitInDeposit, _profitTokenUnit);
		deltaFeesInDepositToken = FixedPointMathLib.fullMulDiv(totalFees, _profitTokenUnitInDeposit, _profitTokenUnit);
	}

	/**
	 * @notice Should update locked profit ratio based on delta profit and fees in deposit tokens
	 * @notice Passes delta profit and delta fees in depositToken decimals
	 */
	function _simulatedUpdateLockedProfitRatio(
		uint256 deltaProfitInDepositToken,
		uint256 deltaFeesInDepositToken,
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	) private view returns (IVaultSimulatorAPI.VaultSnapshot memory) {
		uint256 currentLockedProfitRatio = _simulatedCalculateCurrentLockedProfitRatio(snapshot);

		// compensate deltaProfit for current locked profit ratio
		uint256 _unlockedDeltaProfitInDepositToken = FixedPointMathLib.fullMulDiv(
			deltaProfitInDepositToken,
			DEGRADATION_COEFFICIENT - currentLockedProfitRatio,
			DEGRADATION_COEFFICIENT
		);
		uint256 _totalAssets = snapshot.totalAssets;
		uint256 _deltaProfitRatio = _totalAssets != 0
			? FixedPointMathLib.fullMulDivUp(_unlockedDeltaProfitInDepositToken, DEGRADATION_COEFFICIENT, _totalAssets)
			: 0;
		uint256 _deltaFeesRatio = _totalAssets != 0 ? FixedPointMathLib.fullMulDiv(deltaFeesInDepositToken, DEGRADATION_COEFFICIENT, _totalAssets) : 0;
		uint256 _newLockedProfitRatio = (currentLockedProfitRatio + _deltaProfitRatio > _deltaFeesRatio)
			? currentLockedProfitRatio + _deltaProfitRatio - _deltaFeesRatio
			: 0;

		// calculate the new locked profit ratio based on the total delta ratio from reporting one or more reserves
		uint256 _remainingLockedProfitPeriod;
		if (currentLockedProfitRatio != 0) {
			uint256 _expectedLockedProfitPeriod = DEGRADATION_COEFFICIENT / (snapshot.lockedProfitDegradationRate + snapshot.extraLockedProfitDegradationRate);
			uint256 _timePassed = (block.timestamp > snapshot.lastLockedProfitDegradation) ? block.timestamp - snapshot.lastLockedProfitDegradation : 0;
			_remainingLockedProfitPeriod = (_expectedLockedProfitPeriod > _timePassed) ? _expectedLockedProfitPeriod - _timePassed : 0;
		}
		uint256 _newRemainingLockedProfitPeriod = DEGRADATION_COEFFICIENT / snapshot.lockedProfitDegradationRate;
		uint256 _newExtraLockedProfitDegradationRate = FixedPointMathLib.fullMulDiv(
			snapshot.lockedProfitDegradationRate,
			_remainingLockedProfitPeriod,
			_newRemainingLockedProfitPeriod
		);

		// update state
		snapshot.extraLockedProfitDegradationRate = _newExtraLockedProfitDegradationRate;
		snapshot.lastLockedProfitRatio = _newLockedProfitRatio;
		snapshot.lastLockedProfitDegradation = snapshot.timestamp;
		return snapshot;
	}

	/**
	 * @notice Simulates calculation of profit and loss of a reserve token
	 * @param tokenIndex The reserve token index
	 * @param snapshot The snapshot
	 * @return reserveProfitInReferenceAsset Profit denominated in reference asset
	 * @return reserveLossInReferenceAsset Loss denominated in reference asset
	 */
	function _simulatedReportProfitLoss(
		uint256 tokenIndex,
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	)
		private
		view
		returns (uint256 reserveProfitInReferenceAsset, uint256 reserveLossInReferenceAsset, uint256 reserveValue, IVaultSimulatorAPI.VaultSnapshot memory)
	{
		IVaultSimulatorAPI.VaultTokenSnapshot memory stats = snapshot.tokens[tokenIndex];
		address referenceAsset = VaultTokensLib.referenceAsset();
		uint256 reservePrecision = 10 ** IERC20Metadata(stats.tokenAddress).decimals();
		uint256 reserveBalance = stats.balance;
		uint256 baselineValue = Math.max(stats.lastReportedValue, stats.watermark);
		reserveValue = (reserveBalance != 0) ? VaultTokensLib.tokenReferenceValue(stats.tokenAddress, reservePrecision) : 0;
		if (stats.tokenAddress != referenceAsset) {
			reserveProfitInReferenceAsset = (baselineValue != 0 && reserveValue > baselineValue)
				? FixedPointMathLib.fullMulDiv((reserveValue - baselineValue), reserveBalance, reservePrecision)
				: 0;
			reserveLossInReferenceAsset = (reserveValue < baselineValue)
				? FixedPointMathLib.fullMulDiv((baselineValue - reserveValue), reserveBalance, reservePrecision)
				: 0;
		}
		// 2. report loss
		address depositToken = VaultTokensLib.token();
		uint reserveLossInDepositToken = (depositToken == referenceAsset)
			? reserveLossInReferenceAsset
			: IDynaVaultAPI(vaultManagerSimulatorLibStorage().vault).tokenValueInQuoteAsset(referenceAsset, reserveLossInReferenceAsset, depositToken);
		stats.totalProfit += reserveProfitInReferenceAsset;
		stats.totalLoss += reserveLossInReferenceAsset;
		stats.tokenIdle = reserveBalance;
		if (reserveProfitInReferenceAsset != 0) {
			uint256 deltaDebt = (reserveLossInDepositToken <= stats.depositDebt) ? reserveLossInDepositToken : stats.depositDebt;
			stats.depositDebt -= deltaDebt;
			if (stats.tokenAddress != snapshot.tokens[0].tokenAddress) snapshot.reserveDebt -= deltaDebt;
		}
		snapshot.tokens[tokenIndex] = stats;
		return (reserveProfitInReferenceAsset, reserveLossInReferenceAsset, reserveValue, snapshot);
	}

	/**
	 * @notice simulates calculation of reserve fees
	 * @param tokenAddress address of reserve token
	 * @param tokenIdle amount of token idle of reserve
	 * @param reserveProfitInReferenceAsset profit to report denominated in reference asset
	 * @param managementFeePct management fee ratio
	 * @param performanceFeePct performance fee ratio
	 * @param elapsed time since last report in seconds
	 */
	function _simulatedCalculateReserveFees(
		address tokenAddress,
		uint256 tokenIdle,
		uint256 reserveProfitInReferenceAsset,
		uint256 managementFeePct,
		uint256 performanceFeePct,
		uint256 elapsed
	) private view returns (uint256 managementFee, uint256 totalFees) {
		// calculate all fees in reference asset to be able to sum them
		uint256 managementFeeInReserveAsset = FixedPointMathLib.fullMulDiv(
			FixedPointMathLib.fullMulDiv(tokenIdle, managementFeePct, MAX_BPS),
			elapsed,
			SECS_PER_YEAR
		);
		managementFee = VaultTokensLib.tokenReferenceValue(tokenAddress, managementFeeInReserveAsset);
		uint256 performanceFeeYields = FixedPointMathLib.fullMulDiv(reserveProfitInReferenceAsset, performanceFeePct, MAX_BPS);
		uint256 netPerformanceFee = (performanceFeeYields > managementFee) ? performanceFeeYields - managementFee : 0;
		totalFees = netPerformanceFee + managementFee;
	}

	/**
	 * @notice deltaTotalAssets is not passed since we don't change the asset balances when there are profits in reserves
	 * @param snapshot The vault snapshot used in the simulation
	 * @param reserveFees amount of fees from reserves
	 * @return snapshot with updated values
	 */
	function _simulatedIssueReserveTokenFees(
		IVaultSimulatorAPI.VaultSnapshot memory snapshot,
		IVaultSimulatorAPI.ReserveFees memory reserveFees
	) private view returns (IVaultSimulatorAPI.VaultSnapshot memory) {
		// update snapshot
		snapshot = IDynaVaultAPI(snapshot.vault).simulatedIssueSharesForFeeAmount(
			reserveFees.totalFees,
			VaultTokensLib.referenceAsset(),
			0, // token stats have been updated so we do not need to compensate for the delta in total assets
			snapshot
		);
		return snapshot;
	}

	function simulateTotalAssetsForToken(address token, IVaultSimulatorAPI.VaultSnapshot memory snapshot) external view returns (uint256) {
		uint256 tokenIndex = VaultTokensLib.tokenIndex(token);
		(, , , snapshot) = _simulatedReportReserveAndCalculateFeesToMintAndDeltaProfit(tokenIndex, snapshot);
		// TODO: add _simulateHarvestStrategy which uses simulateReport(Strategy)
		return snapshot.tokens[tokenIndex].tokenIdle + snapshot.tokens[tokenIndex].tokenDebt;
	}

	/**
	 * @notice simulates reporting for a reserve token
	 * @param tokenIndex index of token to report
	 * @param snapshot The vault snapshot used in the simulation
	 */
	function _simulatedReportReserveAndCalculateFeesToMintAndDeltaProfit(
		uint256 tokenIndex,
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	)
		private
		view
		returns (
			IVaultSimulatorAPI.ReserveFees memory reserveFees,
			uint256 reserveDeltaProfitInDepositToken,
			uint256 reserveFeesInDepositToken,
			IVaultSimulatorAPI.VaultSnapshot memory
		)
	{
		// 1. calc profit/loss
		uint256 reserveValue;
		uint256 reserveProfitInReferenceAsset;
		(reserveProfitInReferenceAsset, , reserveValue, snapshot) = _simulatedReportProfitLoss(tokenIndex, snapshot);
		reserveFees.profit = reserveProfitInReferenceAsset;
		// 2. assess fees
		VaultFeesLib.FeesStorage memory fees = VaultFeesLib.getFees();
		IVaultSimulatorAPI.VaultTokenSnapshot memory stats = snapshot.tokens[tokenIndex];
		uint256 elapsed = snapshot.timestamp - stats.lastReport;
		(uint256 managementFeeInReferenceAsset, uint256 totalFeesInReferenceAsset) = _simulatedCalculateReserveFees(
			snapshot.tokens[tokenIndex].tokenAddress,
			stats.tokenIdle,
			reserveProfitInReferenceAsset,
			fees.managementFee,
			fees.performanceFee,
			elapsed
		);
		reserveFees.managementFee = managementFeeInReferenceAsset;
		uint256 _tokenIndex = tokenIndex; // stack too deep
		reserveFees.totalFees = totalFeesInReferenceAsset;
		IVaultSimulatorAPI.VaultSnapshot memory _snapshot = snapshot; // stack too deep
		if (totalFeesInReferenceAsset != 0) _snapshot.totalFees += totalFeesInReferenceAsset;
		// 3. update locked profit in deposit token denomination, but we pass profit and fees in reference asset token units
		address referenceAsset = VaultTokensLib.referenceAsset();
		(reserveDeltaProfitInDepositToken, reserveFeesInDepositToken) = _simulatedCalculateProfitAndFeesInDepositToken(
			referenceAsset,
			reserveProfitInReferenceAsset,
			totalFeesInReferenceAsset
		);
		// 4. record report timestamp
		_snapshot.tokens[_tokenIndex] = _updateLastReport(stats, reserveValue, _snapshot.timestamp);
		_snapshot.totalProfit += reserveProfitInReferenceAsset;
		return (reserveFees, reserveDeltaProfitInDepositToken, reserveFeesInDepositToken, _snapshot);
	}

	/** @dev Updates the last report timestamp and potentially updates the watermark for a given token
	 * @param stats The snapshot token stats
	 * @param referenceValue Reference value for the token
	 */
	function _updateLastReport(
		IVaultSimulatorAPI.VaultTokenSnapshot memory stats,
		uint256 referenceValue,
		uint256 snapShotTimestamp
	) private pure returns (IVaultSimulatorAPI.VaultTokenSnapshot memory) {
		stats.lastReportedValue = referenceValue;
		if (snapShotTimestamp - stats.lastWatermark >= stats.watermarkDuration) {
			stats.watermark = referenceValue;
			stats.lastWatermark = snapShotTimestamp;
		}
		stats.lastReport = snapShotTimestamp;
		return stats;
	}

	/**
	 * @notice Simulates reporting all reserve tokens
	 * @param snapshot The vault snapshot used in the simulation
	 * @return totalReserveFees with the simulated fee values, snapshot with the simulated values
	 * @return snapshot with updated values
	 */
	function simulatedReportAllReserves(
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	) public view returns (IVaultSimulatorAPI.ReserveFees memory totalReserveFees, IVaultSimulatorAPI.VaultSnapshot memory) {
		uint256 totalDeltaProfitInDepositToken;
		uint256 totalFeesInDepositToken;
		uint256 reserveDeltaProfitInDepositToken;
		uint256 reserveFeesInDepositToken;
		uint256 nrOfTokens = snapshot.tokens.length;
		for (uint256 i = 0; i < nrOfTokens; ++i) {
			IVaultSimulatorAPI.ReserveFees memory reserveFees;
			(reserveFees, reserveDeltaProfitInDepositToken, reserveFeesInDepositToken, snapshot) = _simulatedReportReserveAndCalculateFeesToMintAndDeltaProfit(
				i,
				snapshot
			);
			totalDeltaProfitInDepositToken += reserveDeltaProfitInDepositToken;
			totalFeesInDepositToken += reserveFeesInDepositToken;
			totalReserveFees.managementFee += reserveFees.managementFee;
			totalReserveFees.totalFees += reserveFees.totalFees;
		}
		snapshot = _simulatedUpdateLockedProfitRatio(totalDeltaProfitInDepositToken, totalFeesInDepositToken, snapshot);
		snapshot.lockedProfit = _simulatedLockedProfit(snapshot);
		if (totalReserveFees.totalFees != 0) snapshot = _simulatedIssueReserveTokenFees(snapshot, totalReserveFees);
		return (totalReserveFees, snapshot);
	}

	/**
	 * @notice Returns expected amount out from a token swap using the DynaRouter registry
	 * @param tokenIn address of the token to swap
	 * @param amountIn amount of the token to swap
	 * @param tokenOut address of the token wanted
	 * @return estimatedAmountOut expected amount received from from swap
	 */
	function getExpectedAmountOut(address tokenIn, uint256 amountIn, address tokenOut) private view returns (uint256) {
		(uint256 estimatedAmountOut, , ) = IDynaVaultAPI(vaultManagerSimulatorLibStorage().vault).previewSwap(tokenIn, amountIn, tokenOut);
		return estimatedAmountOut;
	}

	/**
	 * @notice simulates rebalance
	 * @param snapshot The vault snapshot used in the simulation
	 */
	function simulatedRebalance(
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	) external view returns (uint256[] memory expectedAmountsOut, IVaultSimulatorAPI.VaultSnapshot memory updatedSnapshot) {
		uint256 nrOfTokens = snapshot.tokens.length;
		expectedAmountsOut = new uint256[](nrOfTokens - 1);
		// 1. report reserves
		(, updatedSnapshot) = simulatedReportAllReserves(snapshot);
		// 2. calculate total and target depositDebt
		uint256 targetDepositDebtRatio = updatedSnapshot.tokens[0].depositDebtRatio;
		uint256 targetDepositDebt = FixedPointMathLib.fullMulDiv(updatedSnapshot.totalDepositDebt, targetDepositDebtRatio, MAX_TOKEN_DEBT_RATIO);
		uint256 depositDebt = updatedSnapshot.tokens[0].depositDebt;
		// 3. rebalance
		address depositToken = updatedSnapshot.tokens[0].tokenAddress;
		if (depositDebt > targetDepositDebt) {
			// we have excess depositTokens to swap to reserves
			uint256 totalToSwap = depositDebt - targetDepositDebt;
			uint256 reserveDebtRatio = MAX_TOKEN_DEBT_RATIO - targetDepositDebtRatio;
			// TODO: withdraw from strategies here
			// swap excess deposit to reserve
			for (uint256 i = 1; i < nrOfTokens; ++i) {
				targetDepositDebtRatio = updatedSnapshot.tokens[i].depositDebtRatio;
				uint256 toSwap = (reserveDebtRatio != 0) ? FixedPointMathLib.fullMulDiv(totalToSwap, targetDepositDebtRatio, reserveDebtRatio) : 0;
				if (toSwap != 0) {
					expectedAmountsOut[i - 1] = getExpectedAmountOut(depositToken, toSwap, updatedSnapshot.tokens[i].tokenAddress);
				}
				bool reverted; // we don't want to revert in a preview so in the case we need to revert we want to return the original state
				(updatedSnapshot, reverted) = _updateDebtAfterSwap(0, toSwap, i, expectedAmountsOut[i - 1], updatedSnapshot);
				if (reverted) return (new uint256[](nrOfTokens - 1), snapshot); // return zero amounts and original state
			}
		} else if (targetDepositDebt > depositDebt) {
			// we need to swap reserves into depositTokens
			for (uint256 i = 1; i < nrOfTokens; ++i) {
				IVaultSimulatorAPI.VaultTokenSnapshot memory stats = updatedSnapshot.tokens[i];
				targetDepositDebt = FixedPointMathLib.fullMulDiv(updatedSnapshot.totalDepositDebt, stats.depositDebtRatio, MAX_TOKEN_DEBT_RATIO);
				if (stats.depositDebt > targetDepositDebt) {
					uint256 toSwap = (stats.depositDebt != 0)
						? FixedPointMathLib.fullMulDiv(stats.tokenIdle + stats.tokenDebt, stats.depositDebt - targetDepositDebt, stats.depositDebt)
						: 0;
					if (toSwap != 0) expectedAmountsOut[i - 1] = getExpectedAmountOut(updatedSnapshot.tokens[i].tokenAddress, toSwap, depositToken);
					bool reverted;
					(updatedSnapshot, reverted) = _updateDebtAfterSwap(i, toSwap, 0, expectedAmountsOut[i - 1], updatedSnapshot);
					if (reverted) return (new uint256[](nrOfTokens - 1), snapshot);
				}
			}
		}
		return (expectedAmountsOut, updatedSnapshot);
	}

	function _updateDebtAfterSwap(
		uint256 tokenInIndex,
		uint256 amountIn,
		uint256 tokenOutIndex,
		uint256 amountOut,
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	) private view returns (IVaultSimulatorAPI.VaultSnapshot memory, bool) {
		IVaultSimulatorAPI.VaultTokenSnapshot memory statsTokenIn = snapshot.tokens[tokenInIndex];
		if (amountIn > statsTokenIn.tokenIdle) return (snapshot, true);
		IVaultSimulatorAPI.VaultTokenSnapshot memory statsTokenOut = snapshot.tokens[tokenOutIndex];
		if (tokenInIndex == 0) {
			// swap deposit token into reserve asset
			uint256 invested = amountIn;
			uint256 allAssets = statsTokenIn.tokenIdle + statsTokenIn.tokenDebt + snapshot.reserveDebt;
			uint256 deltaDebtRatio = Math.min(FixedPointMathLib.fullMulDiv(invested, MAX_BPS, allAssets), statsTokenIn.depositDebtRatio);
			snapshot.reserveDebt += invested;
			statsTokenIn.depositDebt -= Math.min(invested, statsTokenIn.depositDebt);
			statsTokenOut.depositDebt += invested;
			statsTokenOut.depositDebtRatio += deltaDebtRatio;
			statsTokenIn.depositDebtRatio -= deltaDebtRatio;
		} else if (tokenOutIndex == 0) {
			// swap reserve asset into deposit token
			uint256 deltaDebt;
			uint256 deltaDebtRatio;
			{
				// avoid stack too deep
				uint256 sold = amountIn;
				uint256 curDepositDebt = statsTokenIn.depositDebt;
				uint256 tokenAssets = statsTokenIn.tokenIdle + statsTokenIn.tokenDebt;
				uint256 soldRatio = (tokenAssets != 0) ? FixedPointMathLib.fullMulDiv(sold, MAX_BPS, tokenAssets) : MAX_BPS;
				deltaDebt = FixedPointMathLib.fullMulDiv(curDepositDebt, soldRatio, MAX_BPS);
				uint256 allAssets = statsTokenOut.tokenIdle + statsTokenOut.tokenDebt + snapshot.reserveDebt;
				deltaDebtRatio = Math.min(FixedPointMathLib.fullMulDiv(deltaDebt, MAX_BPS, allAssets), statsTokenIn.depositDebtRatio);
			}
			uint256 paidBack = amountOut;
			if (paidBack < deltaDebt) {
				uint256 loss = deltaDebt - paidBack;
				statsTokenIn.totalLoss += loss;
			}
			snapshot.reserveDebt -= deltaDebt;
			statsTokenIn.depositDebt -= deltaDebt;
			// if we have a loss, do not increase tokenOut depositDebt for tokens which have not been paid back
			statsTokenOut.depositDebt += deltaDebt > paidBack ? paidBack : deltaDebt;
			statsTokenIn.depositDebtRatio -= deltaDebtRatio;
			statsTokenOut.depositDebtRatio += deltaDebtRatio;
		} else {
			// swap reserve asset into another reserve asset
			uint256 sold = amountIn;
			uint256 curDepositDebt = statsTokenIn.depositDebt;
			uint256 tokenAssets = statsTokenIn.tokenIdle + statsTokenIn.tokenDebt;
			uint256 deltaDebt = (tokenAssets != 0) ? Math.min(FixedPointMathLib.fullMulDiv(curDepositDebt, sold, tokenAssets), statsTokenIn.depositDebt) : 0;
			uint256 deltaDebtRatio = (curDepositDebt != 0)
				? Math.min(FixedPointMathLib.fullMulDiv(statsTokenIn.depositDebtRatio, deltaDebt, curDepositDebt), statsTokenIn.depositDebtRatio)
				: 0;
			statsTokenIn.depositDebt -= deltaDebt;
			statsTokenOut.depositDebt += deltaDebt;
			statsTokenIn.depositDebtRatio -= deltaDebtRatio;
			statsTokenOut.depositDebtRatio += deltaDebtRatio;
		}
		// update available tokens in vault
		statsTokenIn.tokenIdle -= amountIn;
		statsTokenOut.tokenIdle += amountOut;
		snapshot.tokens[tokenInIndex] = statsTokenIn;
		snapshot.tokens[tokenOutIndex] = statsTokenOut;
		uint256 tokenInPrecision = 10 ** IERC20Metadata(statsTokenIn.tokenAddress).decimals();
		uint256 tokenInReferenceValue = (statsTokenIn.tokenIdle != 0) ? VaultTokensLib.tokenReferenceValue(statsTokenIn.tokenAddress, tokenInPrecision) : 0;
		statsTokenIn = _updateLastReport(statsTokenIn, tokenInReferenceValue, snapshot.timestamp);
		uint256 tokenOutPrecision = 10 ** IERC20Metadata(statsTokenIn.tokenAddress).decimals();
		uint256 tokenOutReferenceValue = (statsTokenIn.tokenIdle != 0) ? VaultTokensLib.tokenReferenceValue(statsTokenOut.tokenAddress, tokenOutPrecision) : 0;
		statsTokenOut = _updateLastReport(statsTokenOut, tokenOutReferenceValue, snapshot.timestamp);
		snapshot.tokens[tokenInIndex] = statsTokenIn;
		snapshot.tokens[tokenOutIndex] = statsTokenOut;
		return (snapshot, false);
	}

	/**
	 * @notice gets fees from strategies lib, updates locked profit ratio and registers gain in strategy.
	 * @param want token  of strategy
	 * @param gain from strategy in want token
	 * @param snapshot The vault snapshot used in the simulation
	 * @return strategyFees amount of fees from strategy
	 * @return snapshot with updated values
	 */
	function _simulatedRegisterStrategyFees(
		address strategy,
		address want,
		uint256 gain,
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	) private view returns (IVaultSimulatorAPI.StrategyFees memory strategyFees, IVaultSimulatorAPI.VaultSnapshot memory) {
		(uint256 strategyManagementFee, uint256 vaultManagementFee, uint256 strategistFee, uint256 vaultPerformanceFee) = VaultStrategiesLib.calcFees(
			strategy,
			gain,
			gain > 0
		);
		// all in want token
		uint256 totalFees = strategyFees.strategistFee +
			strategyFees.strategyManagementFee +
			strategyFees.vaultManagementFee +
			strategyFees.vaultPerformanceFee;
		strategyFees.strategistFee = strategistFee;
		strategyFees.strategyManagementFee = strategyManagementFee;
		strategyFees.vaultManagementFee = vaultManagementFee;
		strategyFees.vaultPerformanceFee = vaultPerformanceFee;
		strategyFees.totalFees = totalFees;
		// TODO: refactor to use new pattern
		//snapshot = _simulatedUpdateLockedProfitRatio(want, gain, totalFees);
		return (strategyFees, snapshot);
	}

	/**
	 * @notice simulates fee shares issuing during report
	 * @param deltaTotalAssets updates total assets in fee shares calculation
	 * @param strategyFees amount of fees from strategy
	 * @param snapshot The vault snapshot used in the simulation
	 */
	function _simulatedIssueStrategyFeeShares(
		uint256 deltaTotalAssets,
		IVaultSimulatorAPI.StrategyFees memory strategyFees,
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	) private view returns (IVaultSimulatorAPI.VaultSnapshot memory) {
		uint256 totalFees = strategyFees.strategistFee +
			strategyFees.strategyManagementFee +
			strategyFees.vaultManagementFee +
			strategyFees.vaultPerformanceFee;
		snapshot = IDynaVaultAPI(snapshot.vault).simulatedIssueSharesForFeeAmount(totalFees, VaultTokensLib.referenceAsset(), deltaTotalAssets, snapshot);
		return snapshot;
	}

	/**
	 * @notice simulates reportStrategy
	 * @param reporter address of reporter, typically a strategy
	 * @param gain amount of gain in strategy
	 * @param debtPayment amount of debt to pay
	 * @param snapshot The vault snapshot used in the simulation
	 */
	function simulatedReportStrategy(
		address reporter,
		uint256 gain,
		uint256 debtPayment,
		IVaultSimulatorAPI.VaultSnapshot memory snapshot
	) public view returns (IVaultSimulatorAPI.VaultSnapshot memory) {
		address want = VaultStrategiesLib.want(reporter);
		IVaultSimulatorAPI.ReserveFees memory reserveFees;
		// issue shares for reserve fees
		(reserveFees, snapshot) = simulatedReportAllReserves(snapshot);
		IVaultSimulatorAPI.StrategyFees memory strategyFees;
		(strategyFees, snapshot) = _simulatedRegisterStrategyFees(reporter, want, gain, snapshot);
		// convert from want to reference asset
		strategyFees.strategistFee = VaultTokensLib.tokenReferenceValue(want, strategyFees.strategistFee);
		strategyFees.strategyManagementFee = VaultTokensLib.tokenReferenceValue(want, strategyFees.strategyManagementFee);
		strategyFees.vaultManagementFee = VaultTokensLib.tokenReferenceValue(want, strategyFees.vaultManagementFee);
		strategyFees.vaultPerformanceFee = VaultTokensLib.tokenReferenceValue(want, strategyFees.vaultPerformanceFee);
		uint256 totalStrategyFeesInReferenceAsset = strategyFees.strategistFee +
			strategyFees.strategyManagementFee +
			strategyFees.vaultManagementFee +
			strategyFees.vaultPerformanceFee;
		// stack too deep
		IVaultSimulatorAPI.VaultSnapshot memory _snapshot = snapshot;
		uint256 _gain = gain;
		address strategy = reporter;
		// issue shares for strategy fees
		if (totalStrategyFeesInReferenceAsset != 0) {
			uint256 gainInReferenceToken = VaultTokensLib.tokenReferenceValue(want, _gain);
			_simulatedIssueStrategyFeeShares(gainInReferenceToken, strategyFees, _snapshot);
		}
		uint256 credit = VaultStrategiesLib.creditAvailable(strategy);
		uint256 debt = VaultStrategiesLib.debtOutstanding(strategy);
		debtPayment = Math.min(debtPayment, debt);
		IVaultManagerAPI manager = IVaultManagerAPI(vaultManagerSimulatorLibStorage().vault);
		uint256 wantTokenIndex = manager.tokenIndex(want);
		if (debtPayment != 0) {
			// simulate decreaseTokenDebt
			uint256 tokenDebtAmount = snapshot.tokens[wantTokenIndex].tokenDebt;
			if (tokenDebtAmount > debtPayment) snapshot.tokens[wantTokenIndex].tokenDebt = tokenDebtAmount - debtPayment;
			debt -= debtPayment;
		}
		if (credit != 0) snapshot.tokens[wantTokenIndex].tokenDebt += credit; // simulate increaseTokenDebt
		uint256 totalAvail = _gain + debtPayment;
		if (totalAvail < credit) _snapshot.tokens[wantTokenIndex].tokenIdle -= credit - totalAvail;
		else if (totalAvail > credit) _snapshot.tokens[wantTokenIndex].tokenIdle += credit - totalAvail;
		return _snapshot;
	}

	/**
	 * @notice Takes a snapshot of a token's strategies current state
	 * @return snapshots A list of VaultStrategySnapshot structs with strategy information for simulating reporting and withdraws
	 */
	function takeStrategiesSnapshot(address tokenAddress) public view returns (IVaultSimulatorAPI.VaultStrategySnapshot[] memory snapshots) {
		IVaultManagerAPI manager = IVaultManagerAPI(IDynaVaultAPI(vaultManagerSimulatorLibStorage().vault).manager());
		address[] memory strategyList = manager.getTokenStrategies(tokenAddress);
		uint256 nrOfStrategies;
		for (; nrOfStrategies < strategyList.length && strategyList[nrOfStrategies] != address(0); ) nrOfStrategies++;
		snapshots = new IVaultSimulatorAPI.VaultStrategySnapshot[](nrOfStrategies);
		if (nrOfStrategies == 0) return snapshots;
		for (uint256 i = 0; i < nrOfStrategies; ++i) {
			StrategyParams memory strategyParams = manager.strategies(strategyList[i]);
			snapshots[i].debtRatio = strategyParams.debtRatio;
			snapshots[i].totalDebt = strategyParams.totalDebt;
		}
	}
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import "@openzeppelin/contracts/utils/math/Math.sol";
import "solady/src/utils/FixedPointMathLib.sol";
import "./interfaces/IDynaStrategyAPI.sol";
import "./interfaces/IReferenceAssetOracle.sol";
import "./utils/Checks.sol";
import "./VaultGovernanceLib.sol";
import "./VaultTokensLib.sol";
import "./VaultFeesLib.sol";

/**
 * @title The VaultStrategies/Lib sub-module is part of the VaultManager module and essentially handles all strategy-related parameters.
 * @notice Vault governance can add a new strategy, migrate a strategy and revoke a strategy.
 * WithdrawalQueue sequence for a want token can be updated.
 * Also existing strategies can be removed and re-added from the tokenStrategies for their corresponding want token.
 * Each strategy has its own debtRatio which represents how many assets a strategy can have under management,
 * prorated on the whole present amount of want tokens (idle+debt), which is then recorded by the totalDebt parameter.
 * The debtRatio basically handles all deposits and withdrawals to the strategy contract via its increase/decrease by governance.
 * Unlike regular vaults, there is no direct deposit execution but only an increase or decrease of said variable.
 * The debtRatio (expressed in 18 decimals; 100e16 = 100.00%) of a strategy is either directly (updateStrategyDebtRatio)
 * or indirectly (investStrategy/liquidateStrategy) configured by a vault manager,
 * dictating how much of the strategy want token from the totalAssets in vault (tokenIdle) and strategies (tokenDebt)
 * should ideally be allocated to a specific strategy. A strategy can do debtPayments during harvest calls to signal
 * a desire to pay back debt to the vault in it's report call. During this report call the vault will wind down excess debt
 * or invest excess credit available from/to the strategy.
 * However, as a little safeguard, the variables minDebtPerHarvest and maxDebtPerHarvest have been introduced
 * which can limit the transfer amount from the vault to a strategy contract per harvest.
 * The sum of the strategy debtRatios with same want token is kept in tokenDebtRatio.
 * The tokenDebtRatio is a desired tokenIdle/(tokenIdle + tokenDebt) ratio for a certain want token,
 * where tokenDebt is the sum of all want tokens given to all strategies using that want token.
 * Each strategy also implements an emergencyShutdown function which withdraws all tokens from the strategy in a harvest scenario.
 * Additionally, a strategy performance fee and strategy management fee can be set which is applied during report.
 * While the other fees are set within the VaultFees sub-module, the fee calculation logic for assets in the strategies is still done inside this module.
 */
library VaultStrategiesLib {
	using Checks for address;
	using Math for uint256;

	/// @dev The storage slot follows EIP1967 to avoid storage collision
	bytes32 private constant STRATEGY_STORAGE_POSITION = bytes32(uint256(keccak256("VaultStrategies.StrategyStorage")) - 1);
	// seconds per year value is based on average seconds per year based on 4 years, one of them being a leap year
	uint256 private constant SECS_PER_YEAR = 31_556_952;
	uint256 private constant MAX_DEBT_RATIO = 100e16; // 100.00%
	uint256 private constant MAX_MANAGEMENT_FEE = 10e2; //  10.00%
	uint256 private constant MAX_PERFORMANCE_FEE = 50e2; //  50.00%
	uint256 private constant MAX_BPS = 100e2; // 100.00%

	/**
	 * @dev Struct to store parameters for each strategy
	 * @param want Address of the token the strategy wants to maximize
	 * @param performanceFee Performance fee percentage for the strategy
	 * @param activation Timestamp when the strategy was activated
	 * @param debtRatio Debt ratio of the strategy (in 18 decimals)
	 * @param minDebtPerHarvest Minimum debt per harvest for the strategy
	 * @param maxDebtPerHarvest Maximum debt per harvest for the strategy
	 * @param lastReport Timestamp of the last report from the strategy
	 * @param totalDebt Total debt of the strategy
	 * @param totalGain Total gain of the strategy
	 * @param totalLoss Total loss of the strategy
	 * @param managementFee Management fee percentage for the strategy
	 */
	struct StrategyParams {
		address want;
		uint256 performanceFee;
		uint256 activation;
		uint256 debtRatio;
		uint256 minDebtPerHarvest;
		uint256 maxDebtPerHarvest;
		uint256 lastReport;
		uint256 totalDebt;
		uint256 totalGain;
		uint256 totalLoss;
		uint256 managementFee;
		bool revoked;
	}

	/**
	 * @dev Struct to store strategy-related storage variables
	 * @notice This struct is used to organize strategy-related data in a single storage slot
	 */
	struct StrategyStorage {
		mapping(address => StrategyParams) strategies;
		//  Debt ratio per token for the Vault across all strategies for that token
		mapping(address => uint256) tokenDebtRatio;
		bool emergencyShutdown;
	}

	/**
	 * @dev Emitted when a strategy's debt ratio is updated
	 * @param caller Address of the account that initiated the update
	 * @param strategy Address of the strategy
	 * @param strategyDebtRatio New debt ratio for the strategy
	 */
	event UpdatedStrategyDebtRatio(address indexed caller, address strategy, uint256 strategyDebtRatio);

	/**
	 * @dev Emitted when a new strategy is added
	 * @param want Address of the want token
	 * @param strategy Address of the strategy
	 */
	event StrategyAdded(address want, address strategy);

	/**
	 * @dev Emitted when a strategy is removed
	 * @param strategy Address of the strategy
	 */
	event RemovedStrategyFromList(address strategy);

	/**
	 * @dev Emitted when a strategy's min/max debt per harvest is updated
	 * @param caller Address of the account that initiated the update
	 * @param strategy Address of the strategy
	 * @param minDebtPerHarvest New minimum debt per harvest
	 * @param maxDebtPerHarvest New maximum debt per harvest
	 */
	event UpdatedStrategyMinMaxDebtPerHarvest(address indexed caller, address strategy, uint256 minDebtPerHarvest, uint256 maxDebtPerHarvest);

	/**
	 * @dev Emitted when a strategy's performance fee is updated
	 * @param caller Address of the account that initiated the update
	 * @param strategy Address of the strategy
	 * @param performanceFee New performance fee for the strategy
	 */
	event UpdatedStrategyPerformanceFee(address indexed caller, address strategy, uint256 performanceFee);

	/**
	 * @dev Emitted when a strategy's management fee is updated
	 * @param caller Address of the account that initiated the update
	 * @param strategy Address of the strategy
	 * @param managementFee New management fee for the strategy
	 */
	event UpdatedStrategyManagementFee(address indexed caller, address strategy, uint256 managementFee);

	/**
	 * @dev Emitted when a strategy is added to the token strategies list
	 * @param caller Address of the account that initiated the addition
	 * @param strategy Address of the strategy added to the queue
	 */
	event AddedStrategyToQueue(address indexed caller, address strategy);

	/**
	 * @dev Emitted when a strategy is migrated
	 * @param caller Address of the account that initiated the migration
	 * @param oldVersion Address of the old strategy version
	 * @param newVersion Address of the new strategy version
	 */
	event MigratedStrategy(address indexed caller, address oldVersion, address newVersion);

	/**
	 * @dev Emitted when a strategy is revoked
	 * @param caller Address of the account that initiated the revocation
	 * @param strategy Address of the revoked strategy
	 */
	event RevokedStrategy(address indexed caller, address strategy);

	/**
	 * @dev Emitted when a strategy is resurrected
	 * @param caller Address of the account that initiated the resurrection
	 * @param strategy Address of the resurrected strategy
	 */
	event ResurrectStrategy(address indexed caller, address strategy);

	/**
	 * @dev Emitted when emergency shutdown status is changed
	 * @param caller Address of the account that initiated the change
	 * @param shutdown New emergency shutdown status
	 */
	event EmergencyShutdown(address indexed caller, bool shutdown);

	error DuplicateStrategy();

	/**
	 * @dev Returns the storage slot for strategy-related data
	 * @return ss StrategyStorage struct pointer
	 */
	function strategyStorage() private pure returns (StrategyStorage storage ss) {
		bytes32 position = STRATEGY_STORAGE_POSITION;
		assembly {
			ss.slot := position
		}
	}

	/**
	 * @dev Returns the want token address for a given strategy (deposit token for strategy)
	 * @param strategy Address of the strategy
	 * @return Address of the want token
	 */
	function want(address strategy) public view returns (address) {
		return strategyStorage().strategies[strategy].want;
	}

	/**
	 * @dev Returns the token debt ratio for a given token
	 * @param token Address of the token
	 * @return Token debt ratio
	 */
	function tokenDebtRatio(address token) external view returns (uint256) {
		return strategyStorage().tokenDebtRatio[token];
	}

	/**
	 * @dev Returns the debt ratio for a given strategy
	 * @param strategy Address of the strategy
	 * @return Debt ratio of the strategy
	 */
	function debtRatio(address strategy) external view returns (uint256) {
		return strategyStorage().strategies[strategy].debtRatio;
	}

	/**
	 * @dev Returns the strategy parameters for a given strategy
	 * @param strategy Address of the strategy
	 * @return StrategyParams struct containing strategy parameters
	 */
	function strategyParams(address strategy) external view returns (StrategyParams memory) {
		return strategyStorage().strategies[strategy];
	}

	/**
	 * @dev Checks if a strategy is active
	 * @param strategy Address of the strategy to check
	 * @notice Reverts if the strategy is not active
	 */
	function requireActive(address strategy) public view {
		require(strategyStorage().strategies[strategy].activation != 0, "ERR_INACTIVE");
	}

	/**
	 * @dev Returns the emergency shutdown status
	 * @return Boolean indicating if emergency shutdown is active
	 */
	function isEmergencyShutdown() external view returns (bool) {
		return strategyStorage().emergencyShutdown;
	}

	/**
	 * @dev Updates the debt ratio for a given strategy
	 * @param strategy Address of the strategy
	 * @param strategyDebtRatio New debt ratio for the strategy
	 */
	function updateStrategyDebtRatio(address strategy, uint256 strategyDebtRatio) external {
		VaultGovernanceLib.onlyManagementOrGovernance();
		requireActive(strategy);
		StrategyStorage storage _storage = strategyStorage();

		address token = _storage.strategies[strategy].want;

		// cache storage values
		uint256 _updatedTokenDebtRatio = _storage.tokenDebtRatio[token] + strategyDebtRatio - _storage.strategies[strategy].debtRatio;
		require(_updatedTokenDebtRatio <= MAX_DEBT_RATIO, "ERR_MAX_DEBT_RATIO");

		// update storage
		_storage.strategies[strategy].debtRatio = strategyDebtRatio;
		_storage.tokenDebtRatio[token] = _updatedTokenDebtRatio;

		emit UpdatedStrategyDebtRatio(msg.sender, strategy, strategyDebtRatio);
	}

	/**
	 * @dev Updates the minimum and maximum debt per harvest for a given strategy
	 * @param strategy Address of the strategy
	 * @param minDebtPerHarvest New minimum debt per harvest
	 * @param maxDebtPerHarvest New maximum debt per harvest
	 */
	function updateStrategyMinMaxDebtPerHarvest(address strategy, uint256 minDebtPerHarvest, uint256 maxDebtPerHarvest) external {
		VaultGovernanceLib.onlyManagementOrGovernance();
		requireActive(strategy);
		require(minDebtPerHarvest <= maxDebtPerHarvest, "ERR_MINMAX_DEBT_PER_HARVEST");
		StrategyStorage storage _storage = strategyStorage();
		_storage.strategies[strategy].minDebtPerHarvest = minDebtPerHarvest;
		_storage.strategies[strategy].maxDebtPerHarvest = maxDebtPerHarvest;
		emit UpdatedStrategyMinMaxDebtPerHarvest(msg.sender, strategy, minDebtPerHarvest, maxDebtPerHarvest);
	}

	/**
	 * @dev Updates the performance fee for a given strategy
	 * @param strategy Address of the strategy
	 * @param strategyPerformanceFee New performance fee for the strategy
	 */
	function updateStrategyPerformanceFee(address strategy, uint256 strategyPerformanceFee) external {
		VaultGovernanceLib.onlyGovernance();
		requireActive(strategy);
		require(strategyPerformanceFee <= MAX_PERFORMANCE_FEE, "ERR_MAX_PERFORMANCE_FEE");
		strategyStorage().strategies[strategy].performanceFee = strategyPerformanceFee;
		emit UpdatedStrategyPerformanceFee(msg.sender, strategy, strategyPerformanceFee);
	}

	/**
	 * @dev Updates the management fee for a given strategy
	 * @param strategy Address of the strategy
	 * @param strategyManagementFee New management fee for the strategy
	 */
	function updateStrategyManagementFee(address strategy, uint256 strategyManagementFee) external {
		VaultGovernanceLib.onlyGovernance();
		requireActive(strategy);
		require(strategyManagementFee <= MAX_MANAGEMENT_FEE, "ERR_MAX_MANAGEMENT_FEE");
		strategyStorage().strategies[strategy].managementFee = strategyManagementFee;
		emit UpdatedStrategyManagementFee(msg.sender, strategy, strategyManagementFee);
	}

	/**
	 * @dev Revokes a strategy, setting its debt ratio to 0
	 * @param strategy Address of the strategy to revoke
	 */
	function _revokeStrategy(address strategy) private {
		StrategyStorage storage _storage = strategyStorage();
		_storage.tokenDebtRatio[_storage.strategies[strategy].want] -= _storage.strategies[strategy].debtRatio;
		_storage.strategies[strategy].debtRatio = 0;
		_storage.strategies[strategy].revoked = true;
		emit RevokedStrategy(msg.sender, strategy);
	}

	/**
	 * @dev Adds a new strategy to the vault
	 * @param strategy Address of the strategy to add
	 * @param minDebtPerHarvest Minimum debt per harvest for the strategy
	 * @param maxDebtPerHarvest Maximum debt per harvest for the strategy
	 * @param performanceFee Performance fee for the strategy
	 */
	function addStrategy(address strategy, uint256 minDebtPerHarvest, uint256 maxDebtPerHarvest, uint256 performanceFee) external {
		VaultGovernanceLib.onlyGovernance();
		strategy.requireNonZeroAddress();
		require(minDebtPerHarvest <= maxDebtPerHarvest, "ERR_MINMAX_DEBT_PER_HARVEST");
		require(performanceFee <= MAX_PERFORMANCE_FEE, "ERR_MAX_PERFORMANCE_FEE");
		StrategyStorage storage _storage = strategyStorage();
		if (_storage.strategies[strategy].activation != 0) revert DuplicateStrategy();
		address _want = IDynaStrategyAPI(strategy).want();
		VaultTokensLib.tokenExists(_want);
		_storage.strategies[strategy] = StrategyParams({
			want: _want,
			performanceFee: performanceFee,
			activation: block.timestamp,
			debtRatio: 0,
			minDebtPerHarvest: minDebtPerHarvest,
			maxDebtPerHarvest: maxDebtPerHarvest,
			lastReport: block.timestamp,
			totalDebt: 0,
			totalGain: 0,
			totalLoss: 0,
			managementFee: 0,
			revoked: false
		});
		// Add strategy to the end of the token strategies list
		VaultTokensLib.addToTokenStrategies(_want, strategy);
		emit StrategyAdded(_want, strategy);
	}

	/**
	 * @dev Migrates a strategy from an old version to a new version
	 * @notice Strategy must successfully migrate all capital and positions to new Strategy,
	 * or else this will upset the balance of the Vault.
	 * The new Strategy should be "empty" e.g. have no prior commitments to this Vault, otherwise it could have issues.
	 * @param oldVersion Address of the old strategy version
	 * @param newVersion Address of the new strategy version
	 */
	function migrateStrategy(address oldVersion, address newVersion) external {
		VaultGovernanceLib.onlyGovernance();
		newVersion.requireNonZeroAddress();
		StrategyStorage storage _storage = strategyStorage();
		StrategyParams memory strategyOldVersion = _storage.strategies[oldVersion];
		require(strategyOldVersion.activation != 0, "!old.active");
		require(_storage.strategies[newVersion].activation == 0, "new.active");
		require(strategyOldVersion.want == IDynaStrategyAPI(newVersion).want(), "!want");
		_revokeStrategy(oldVersion);

		//  _revokeStrategy will lower the debtRatio
		_storage.tokenDebtRatio[strategyOldVersion.want] += strategyOldVersion.debtRatio;
		_storage.strategies[oldVersion].totalDebt = 0;

		_storage.strategies[newVersion] = StrategyParams({
			want: strategyOldVersion.want,
			performanceFee: strategyOldVersion.performanceFee,
			activation: strategyOldVersion.lastReport,
			debtRatio: strategyOldVersion.debtRatio,
			minDebtPerHarvest: strategyOldVersion.minDebtPerHarvest,
			maxDebtPerHarvest: strategyOldVersion.maxDebtPerHarvest,
			lastReport: strategyOldVersion.lastReport,
			totalDebt: strategyOldVersion.totalDebt,
			totalGain: 0,
			totalLoss: 0,
			managementFee: strategyOldVersion.managementFee,
			revoked: false
		});

		IDynaStrategyAPI(oldVersion).migrate(newVersion);

		VaultTokensLib.replaceInTokenStrategies(want(oldVersion), oldVersion, newVersion);
		emit MigratedStrategy(msg.sender, oldVersion, newVersion);
	}

	/**
	 * @dev Revoke a Strategy, setting its debt limit to 0 and preventing any
	 *     future deposits.
	 *
	 *     This function should only be used in the scenario where the Strategy is
	 *     being retired but no migration of the positions are possible, or in the
	 *     extreme scenario that the Strategy needs to be put into "Emergency Exit"
	 *     mode in order for it to exit as quickly as possible. The latter scenario
	 *     could be for any reason that is considered "critical" that the Strategy
	 *     exits its position as fast as possible, such as a sudden change in market
	 *     conditions leading to losses, or an imminent failure in an external
	 *     dependency.
	 *
	 *     This may only be called by governance, the guardian, or the Strategy
	 *     itself. Note that a Strategy will only revoke itself during emergency
	 *     shutdown.
	 * @param strategy Address of the strategy to revoke
	 */
	function revokeStrategy(address strategy) external {
		VaultGovernanceLib.onlyEmergencyAuthorized();
		require(strategyStorage().strategies[strategy].debtRatio != 0, "ERR_DEBT_RATIO");
		_revokeStrategy(strategy);
	}

	/**
	 * @dev Resurrects a strategy by undoing a revoke
	 */
	function resurrectStrategy(address strategy) external {
		VaultGovernanceLib.onlyGovernance();
		strategyStorage().strategies[strategy].revoked = false;
		emit ResurrectStrategy(msg.sender, strategy);
	}

	/**
	 * @dev Adds a strategy to the token strategies list
	 * @param strategy Address of the strategy to add to the queue
	 */
	function addStrategyToList(address strategy) external {
		VaultGovernanceLib.onlyManagementOrGovernance();
		requireActive(strategy);
		VaultTokensLib.addToTokenStrategies(want(strategy), strategy);
		emit AddedStrategyToQueue(msg.sender, strategy);
	}

	/**
	 * @dev Removes a strategy from the token strategies list
	 * @param strategy Address of the strategy to remove from the token strategies list
	 */
	function removeStrategyFromList(address strategy) external {
		VaultGovernanceLib.onlyManagementOrGovernance();
		VaultTokensLib.removeFromTokenStrategies(want(strategy), strategy);
		emit RemovedStrategyFromList(strategy);
	}

	/**
	 * @dev Sets the new debt ratio for a strategy
	 * @notice Reverts when a strategy has been revoked to avoid changing its debt ratio
	 * @param strategy Address of the strategy to check
	 */
	function _setNewStrategyDebtRatio(address strategy, uint256 newStrategyDebtRatio) private {
		if (strategyStorage().strategies[strategy].revoked) revert DynaVaultErrors.UnableToChangeDebtRatioOnRevokedStrategy();
		StrategyStorage storage _storage = strategyStorage();
		uint256 oldStrategyDebtRatio = _storage.strategies[strategy].debtRatio;
		_storage.strategies[strategy].debtRatio = newStrategyDebtRatio;
		address _want = _storage.strategies[strategy].want;
		uint256 _newTokenDebtRatio = _storage.tokenDebtRatio[_want] + newStrategyDebtRatio - oldStrategyDebtRatio;
		require(_newTokenDebtRatio <= MAX_DEBT_RATIO, "ERR_MAX_DEBT_RATIO");
		_storage.tokenDebtRatio[_want] = _newTokenDebtRatio;
	}

	/** @notice amount is in deposit token decimals */
	function increaseStrategyDebtRatioByInvestmentAmount(address strategy, uint256 amount) internal {
		StrategyStorage storage _storage = strategyStorage();
		address _want = _storage.strategies[strategy].want;
		uint256 _tokenIdle = VaultTokensLib.tokenIdle(_want); // want token decimals
		require(_tokenIdle >= amount, "!tokenIdle");
		uint256 _tokenDebt = VaultTokensLib.tokenDebt(_want); // in deposit token decimals
		uint256 tokenTotalAssets = _tokenIdle + _tokenDebt;
		uint256 strategyDebtLimit = FixedPointMathLib.fullMulDiv(_storage.strategies[strategy].debtRatio, tokenTotalAssets, MAX_DEBT_RATIO);
		uint256 newStrategyDebtRatio = FixedPointMathLib.fullMulDiv(strategyDebtLimit + amount, MAX_DEBT_RATIO, tokenTotalAssets);
		// update debt ratio
		_setNewStrategyDebtRatio(strategy, newStrategyDebtRatio);
	}

	/**
	 * @dev Decreases the debt of a strategy
	 * @param strategy Address of the strategy
	 * @param amount Amount of tokens withdrawn from the strategy
	 * @param givenTokenTotalAssets Amount of total assets to use
	 * @notice This function can only be called by the vault
	 */
	function decreaseStrategyDebtRatioByInvestmentAmount(address strategy, uint256 amount, uint256 givenTokenTotalAssets) internal {
		StrategyStorage storage _storage = strategyStorage();
		require(_storage.strategies[strategy].totalDebt >= amount, "!strategy.totalDebt");
		uint256 strategyDebtLimit = Math.max(
			FixedPointMathLib.fullMulDiv(_storage.strategies[strategy].debtRatio, givenTokenTotalAssets, MAX_DEBT_RATIO),
			amount
		);
		// update debt ratio
		_setNewStrategyDebtRatio(strategy, ((strategyDebtLimit - amount) * MAX_DEBT_RATIO) / givenTokenTotalAssets);
	}

	/**
	 * @dev Decreases the debt of a strategy
	 * @param strategy Address of the strategy
	 * @param withdrawn Amount of tokens withdrawn from the strategy
	 * @notice This function can only be called by the vault
	 */
	function decreaseStrategyDebt(address strategy, uint256 withdrawn) external {
		VaultGovernanceLib.onlyVault();
		StrategyStorage storage _storage = strategyStorage();
		_storage.strategies[strategy].totalDebt -= withdrawn;
		VaultTokensLib.decreaseTokenDebt(_storage.strategies[strategy].want, withdrawn);
	}

	/**
	 * @dev Returns the total debt of a strategy
	 * @param strategy Address of the strategy
	 * @return uint256 Total debt of the strategy
	 */
	function strategyDebt(address strategy) external view returns (uint256) {
		return strategyStorage().strategies[strategy].totalDebt;
	}

	/**
	 * @dev Calculates the outstanding debt of a strategy
	 * @param strategy Address of the strategy
	 * @return uint256 Outstanding debt of the strategy
	 */
	function debtOutstanding(address strategy) public view returns (uint256) {
		StrategyStorage storage _storage = strategyStorage();
		if (_storage.tokenDebtRatio[_storage.strategies[strategy].want] == 0 || _storage.emergencyShutdown) {
			return _storage.strategies[strategy].totalDebt;
		}
		uint256 strategyDebtLimit = (_storage.strategies[strategy].debtRatio * VaultTokensLib.totalTokenAssets(_storage.strategies[strategy].want)) /
			MAX_DEBT_RATIO;
		//
		uint256 strategyTotalDebt = _storage.strategies[strategy].totalDebt;

		if (strategyTotalDebt <= strategyDebtLimit) {
			return 0;
		} else {
			return strategyTotalDebt - strategyDebtLimit;
		}
	}

	/**
	 * @dev Calculates the available credit for a strategy
	 * @param strategy Address of the strategy
	 * @return uint256 Available credit for the strategy
	 */
	function creditAvailable(address strategy) public view returns (uint256) {
		StrategyStorage storage _storage = strategyStorage();
		if (_storage.strategies[strategy].activation == 0) return 0;
		if (_storage.emergencyShutdown) return 0;
		address _want = _storage.strategies[strategy].want;
		uint256 vaultTokenDebt = VaultTokensLib.tokenDebt(_want);
		uint256 vaultTotalAssets = VaultTokensLib.tokenIdle(_want) + vaultTokenDebt;
		uint256 vaultDebtLimit = FixedPointMathLib.fullMulDiv(_storage.tokenDebtRatio[_want], vaultTotalAssets, MAX_DEBT_RATIO);
		uint256 strategyDebtLimit = FixedPointMathLib.fullMulDiv(_storage.strategies[strategy].debtRatio, vaultTotalAssets, MAX_DEBT_RATIO);
		uint256 strategyTotalDebt = _storage.strategies[strategy].totalDebt;
		uint256 strategyMinDebtPerHarvest = _storage.strategies[strategy].minDebtPerHarvest;
		uint256 strategyMaxDebtPerHarvest = _storage.strategies[strategy].maxDebtPerHarvest;
		// Exhausted credit line
		if (strategyDebtLimit <= strategyTotalDebt || vaultDebtLimit <= vaultTokenDebt) return 0;
		// Start with debt limit left for the Strategy
		uint256 available = strategyDebtLimit - strategyTotalDebt;
		// Adjust by the global debt limit left
		available = Math.min(available, vaultDebtLimit - vaultTokenDebt);
		// Can only borrow up to what the contract has in reserve
		available = Math.min(available, VaultTokensLib.tokenIdle(_want));
		// Adjust by min and max borrow limits (per harvest)
		if (available < strategyMinDebtPerHarvest) return 0;
		else return Math.min(available, strategyMaxDebtPerHarvest);
	}

	/**
	 * @dev Sets the emergency shutdown status
	 * @notice In the extreme scenario that the Vault needs to be put into "Emergency Exit"
	 * mode in order for it to exit all strategies as quickly as possible. This scenario
	 * could be for any reason that is considered "critical" that the Strategies
	 * exits its position as fast as possible, such as a sudden change in market
	 * conditions leading to losses, or an imminent failure in an external dependency.
	 * @param shutdown Boolean indicating whether to activate or deactivate emergency shutdown
	 * @notice Only emergency authorized accounts can activate shutdown, only governance can deactivate
	 */
	function setEmergencyShutdown(bool shutdown) external {
		if (shutdown) {
			VaultGovernanceLib.onlyEmergencyAuthorized();
		} else {
			VaultGovernanceLib.onlyGovernance();
		}
		strategyStorage().emergencyShutdown = shutdown;
		emit EmergencyShutdown(msg.sender, shutdown);
	}

	/**
	 * @dev Registers a loss for a strategy
	 * @param strategyAddress Address of the strategy
	 * @param loss Amount of loss to register
	 */
	function registerLoss(address strategyAddress, uint256 loss) external {
		StrategyStorage storage _storage = strategyStorage();
		uint256 strategyTotalDebt = _storage.strategies[strategyAddress].totalDebt;
		if (loss > strategyTotalDebt) loss = strategyTotalDebt;
		address _want = _storage.strategies[strategyAddress].want;
		if (_storage.strategies[strategyAddress].debtRatio != 0) {
			// NOTE: This calculation is more precise than yearn
			uint256 newDebtRatio = ((strategyTotalDebt - loss) * MAX_DEBT_RATIO) / (VaultTokensLib.totalTokenAssets(_want) - loss);
			uint256 debtRatioChange = (_storage.strategies[strategyAddress].debtRatio > newDebtRatio)
				? _storage.strategies[strategyAddress].debtRatio - newDebtRatio
				: 0;
			_storage.strategies[strategyAddress].debtRatio -= debtRatioChange;
			if (_storage.tokenDebtRatio[_want] > debtRatioChange) {
				_storage.tokenDebtRatio[_want] -= debtRatioChange;
			} else {
				_storage.tokenDebtRatio[_want] = 0;
			}
		}
		_storage.strategies[strategyAddress].totalLoss += loss;
		_storage.strategies[strategyAddress].totalDebt = strategyTotalDebt - loss;
		VaultTokensLib.decreaseTokenDebt(_want, loss);
	}

	/**
	 * @dev Calculates the expected return for a strategy
	 * @param strategy Address of the strategy
	 * @return uint256 Expected return for the strategy
	 */
	function expectedReturn(address strategy) external view returns (uint256) {
		StrategyStorage storage _storage = strategyStorage();
		uint256 strategy_lastReport = _storage.strategies[strategy].lastReport;
		uint256 timeSinceLastHarvest = block.timestamp - strategy_lastReport;
		uint256 totalHarvestTime = strategy_lastReport - _storage.strategies[strategy].activation;

		if (
			timeSinceLastHarvest != 0 &&
			totalHarvestTime != 0 &&
			_storage.strategies[strategy].activation != 0 &&
			_storage.strategies[strategy].totalGain > _storage.strategies[strategy].totalLoss
		) {
			uint256 totalReturns = _storage.strategies[strategy].totalGain - _storage.strategies[strategy].totalLoss;
			return FixedPointMathLib.fullMulDiv(totalReturns, timeSinceLastHarvest, totalHarvestTime);
		} else {
			return 0;
		}
	}

	/**
	 * @dev Calculates various fees for a strategy
	 * @param strategy Address of the strategy
	 * @param gainAmount Amount of gain
	 * @param performance Boolean indicating whether to calculate performance fees
	 * @return strategy_management_fee Management fee for the strategy
	 * @return vault_management_fee Management fee for the vault
	 * @return strategist_fee Fee for the strategist
	 * @return vault_performance_fee Performance fee for the vault
	 */
	function calcFees(
		address strategy,
		uint256 gainAmount,
		bool performance
	) external view returns (uint256 strategy_management_fee, uint256 vault_management_fee, uint256 strategist_fee, uint256 vault_performance_fee) {
		// fix stack too deep
		address strategyAddress = strategy;
		uint256 gain = gainAmount;
		bool _performance = performance;
		VaultFeesLib.FeesStorage memory fees = VaultFeesLib.getFees();
		StrategyParams storage _strategyParams = strategyStorage().strategies[strategyAddress];
		uint256 duration = block.timestamp - _strategyParams.lastReport;

		if (duration == 0) {
			return (0, 0, 0, 0);
		}

		{
			// fix stack too deep
			uint256 vaultManagementFeePct = fees.managementFee;
			uint256 strategyManagementFeePct = _strategyParams.managementFee;
			uint256 _strategyDebt = _strategyParams.totalDebt;
			// delegated assets are already paying management fee elsewhere
			uint256 delegatedAssets = IDynaStrategyAPI(strategyAddress).delegatedAssets();
			// we subtract delegated assets from assetsUnderManagement to avoid double tax
			uint256 assetsUnderManagement = (_strategyDebt > delegatedAssets) ? (_strategyDebt - delegatedAssets) : 0;

			vault_management_fee = FixedPointMathLib.fullMulDiv(
				FixedPointMathLib.fullMulDiv(assetsUnderManagement, vaultManagementFeePct, MAX_BPS), // ratio of assets
				duration,
				SECS_PER_YEAR // ratio of year
			);

			strategy_management_fee = FixedPointMathLib.fullMulDiv(
				FixedPointMathLib.fullMulDiv(assetsUnderManagement, strategyManagementFeePct, MAX_BPS), // ratio of assets
				duration,
				SECS_PER_YEAR // ratio of year
			);
		}

		if (_performance) {
			uint256 vaultPerformanceFeePct = fees.performanceFee;
			uint256 strategyPerformanceFeePct = _strategyParams.performanceFee;
			strategist_fee = FixedPointMathLib.fullMulDiv(gain, strategyPerformanceFeePct, MAX_BPS);
			vault_performance_fee = FixedPointMathLib.fullMulDiv(gain, vaultPerformanceFeePct, MAX_BPS);
			// apply management fee seniority principle
			strategist_fee = (strategist_fee > strategy_management_fee) ? strategist_fee - strategy_management_fee : 0;
			vault_performance_fee = (vault_performance_fee > vault_management_fee) ? vault_performance_fee - vault_management_fee : 0;
		}
	}

	/**
	 * @dev Updates the last report timestamp for a strategy
	 * @param strategyAddress Address of the strategy
	 */
	function updateLastReport(address strategyAddress) external {
		strategyStorage().strategies[strategyAddress].lastReport = block.timestamp;
	}

	/**
	 * @dev returns the last report timestamp for a strategy
	 * @param strategyAddress Address of the strategy
	 */
	function lastReport(address strategyAddress) external view returns (uint256) {
		return strategyStorage().strategies[strategyAddress].lastReport;
	}

	/**
	 * @dev Registers a gain for a strategy
	 * @param strategyAddress Address of the strategy
	 * @param gain Amount of gain to register
	 */
	function registerGain(address strategyAddress, uint256 gain) external {
		strategyStorage().strategies[strategyAddress].totalGain += gain;
	}

	/**
	 * @dev Decreases the debt of a strategy
	 * @param strategyAddress Address of the strategy
	 * @param debtPayment Amount of debt to decrease
	 */
	function decreaseDebt(address strategyAddress, uint256 debtPayment) external {
		strategyStorage().strategies[strategyAddress].totalDebt -= debtPayment;
	}

	/**
	 * @dev Increases the debt of a strategy
	 * @param strategyAddress Address of the strategy
	 * @param _debt Amount of debt to increase
	 */
	function increaseDebt(address strategyAddress, uint256 _debt) external {
		strategyStorage().strategies[strategyAddress].totalDebt += _debt;
	}

	/**
	 * @dev Converts ETH amount to want token amount
	 * @param amount Amount of ETH to convert
	 * @param wethAddress Address of the WETH token
	 * @param strategyAddress Address of the strategy
	 * @return value Amount in want token
	 */
	function ethToWant(uint256 amount, address wethAddress, address strategyAddress) external view returns (uint256 value) {
		address _want = strategyStorage().strategies[strategyAddress].want;
		if (_want == wethAddress) return amount;
		(uint256 price, ) = IReferenceAssetOracle(IDynaVaultAPI(VaultGovernanceLib.vault()).referenceAssetOracle()).getPrice(wethAddress, _want);
		return (amount * price) / 1e18;
	}
}

